1|// Step 3: one Jev call per scene, Meta override on low confidence.
2|// Hard failures record the error and continue; they never invent a vector.
3|import { readFileSync, writeFileSync } from "node:fs";
4|import { join } from "node:path";
5|import { EMOTIONS } from "../core/types";
6|import type { AnalyzedScene, Book, EmotionId, Scene, SceneEmotion } from "../core/types";
