11|import type { JevClient } from "./jev";
12|import type { MetaClient } from "./meta";
13|import { jevCostUsd, metaCostUsd } from "./prices";
14|
15|const OVERRIDE_SCHEMA = {
16|  type: "object",
17|  properties: {
18|    vector: {
19|      type: "object",
20|      properties: Object.fromEntries(EMOTIONS.map((id) => [id, { type: "number" }])),
21|      required: [...EMOTIONS],
22|      additionalProperties: false,
23|    },
24|    reason: { type: "string" },
25|  },
26|  required: ["vector", "reason"],
27|  additionalProperties: false,
28|};
29|
30|export interface ClassifyMetaUsage {
31|  model: string;
32|  requests: number;
33|  promptTokens: number;
34|  cachedTokens: number;
35|  completionTokens: number;
36|  costUsd: number;
37|}
38|
39|async function classifyScene(
40|  scene: Scene,
41|  text: string,
42|  bookTitle: string,
43|  chapterTitle: string,
44|  deps: { jev: JevClient; meta: MetaClient },
45|  metaUsage: ClassifyMetaUsage,
46|): Promise<SceneEmotion> {
47|  let jev;
48|  try {
49|    jev = await deps.jev.classify({ book: bookTitle, chapter: chapterTitle, sceneTitle: scene.title, scene: text });
50|  } catch (error) {
51|    return { jev: null, muse_override: null, final: null, error: `jev failed: ${(error as Error).message}` };
52|  }
53|  if (!needsOverride({ choice: jev.choice, confidence: jev.confidence, probabilities: jev.vector })) {
54|    const final = jevFinal({ probabilities: jev.vector, intensity: jev.intensity, tempo: jev.tempo });
55|    return { jev, muse_override: null, final, error: final === null ? "jev vector renormalizes to zero" : null };
56|  }
57|  try {
58|    const result = await deps.meta.completeJson({
59|      system: "You score soundtrack mood as a probability mix over 8 feelings. Answer with JSON only.",
60|      user:
61|        `Scene "${scene.title}": ${text}\nJev vector: ${JSON.stringify(jev.vector)} ` +
62|        `(choice ${jev.choice}, confidence ${jev.confidence}). ` +
63|        `Give a probability mix over the 8 feelings only, plus one short sentence for reason.`,
64|      schemaName: "emotion_override",
65|      schema: OVERRIDE_SCHEMA,
66|    });
67|    metaUsage.requests += 1;
68|    metaUsage.promptTokens += result.promptTokens;
69|    metaUsage.cachedTokens += result.cachedTokens;
70|    metaUsage.completionTokens += result.completionTokens;
71|    const parsed = result.data as { vector?: Partial<Record<EmotionId, number>>; reason?: unknown };
72|    const vector = renormalize8(parsed.vector ?? {});
73|    if (vector === null) {
74|      return { jev, muse_override: null, final: null, error: "override vector is all zero" };
75|    }
76|    const override = { vector, reason: String(parsed.reason ?? ""), model: deps.meta.model };
77|    return { jev, muse_override: override, final: { vector, intensity: jev.intensity, tempo: jev.tempo }, error: null };
78|  } catch (error) {
79|    return { jev, muse_override: null, final: null, error: `override failed: ${(error as Error).message}` };
80|  }
81|}
82|
83|export async function runClassify(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
84|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
85|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
86|    scenes: Scene[];
87|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
88|  };
89|  const outPath = join(ctx.dir, "analysis.json");
90|  if (!ctx.force) {
91|    const fresh = readIfFresh<{ textVersion: string; scenes: AnalyzedScene[] }>(outPath, book.textVersion);
92|    if (fresh) return fresh.scenes;
93|  }
94|  const metaUsage: ClassifyMetaUsage = { model: deps.meta.model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 };
95|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
96|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
97|  let jevInputTokens = 0;
98|  let jevOutputTokens = 0;
99|  let jevRequests = 0;
100|  const scenes = await runPool(scenesFile.scenes, 4, async (scene) => {
101|    const texts: string[] = [];
102|    for (let n = scene.start_n; n <= scene.end_n; n++) texts.push(byN.get(n)?.text ?? "");
103|    const emotion = await classifyScene(scene, texts.join("\n"), book.title, chapterTitle.get(scene.ch) ?? "", deps, metaUsage);
104|    if (emotion.jev) {
105|      jevInputTokens += emotion.jev.inputTokens;
106|      jevOutputTokens += emotion.jev.outputTokens;
107|      jevRequests += 1;
108|    }
109|    return { ...scene, ...emotion };
110|  });
111|  metaUsage.costUsd = metaCostUsd({ prompt: metaUsage.promptTokens, cached: metaUsage.cachedTokens, completion: metaUsage.completionTokens });
112|  const jevCost = jevCostUsd(jevInputTokens);
113|  const segment = scenesFile.provenance.meta;
114|  const metaTotal = {
115|    model: deps.meta.model,
116|    requests: segment.requests + metaUsage.requests,
117|    prompt_tokens: segment.prompt_tokens + metaUsage.promptTokens,
118|    cached_tokens: segment.cached_tokens + metaUsage.cachedTokens,
119|    completion_tokens: segment.completion_tokens + metaUsage.completionTokens,
120|    cost_usd: segment.cost_usd + metaUsage.costUsd,
121|  };
122|  const overrides = scenes.filter((s) => s.muse_override !== null).length;
123|  writeFileSync(
124|    outPath,
125|    `${JSON.stringify({
126|      bookId: book.id,
127|      textVersion: book.textVersion,
128|      scenes,
129|      override_rate: scenes.length > 0 ? overrides / scenes.length : 0,
130|      provenance: {
131|        date: new Date().toISOString(),
132|        jev: { model: deps.jev.model, requests: jevRequests, input_tokens: jevInputTokens, output_tokens: jevOutputTokens, cost_usd: jevCost },
133|        meta: metaTotal,
134|        total_cost_usd: jevCost + metaTotal.cost_usd,
135|      },
136|    })}\n`,
137|  );
138|  return scenes;
139|}

